<template><div class="map" role="img" aria-label="工地 GIS 地图占位"><div class="grid"></div><div class="line a"></div><div class="line b"></div><div class="fence fa">2# 吊装作业区</div><div class="fence fb">高风险临时围栏</div><button v-for="m in markers" :key="m.id" class="marker" :class="m.type" :style="styleOf(m)" type="button" @click="active=m"><span>{{m.short||m.name?.slice(0,1)}}</span><b>{{m.name}}</b></button><div class="badge">地图 API 待配置 · 数字孪生占位层</div><div v-if="active" class="pop"><strong>{{active.name}}</strong><span>{{active.typeLabel||active.type}} · {{active.statusLabel||'在线'}}</span><button @click="active=null">关闭</button></div><div class="legend"><span v-for="l in legend" :key="l.label"><i :style="{background:l.color}"></i>{{l.label}}</span></div></div></template>
<script setup>import{ref}from'vue';const markers=ref([{id:'c1',name:'QT-021',short:'C',type:'crane',typeLabel:'吊车',x:31,y:29,statusLabel:'作业中'},{id:'c2',name:'QT-018',short:'C',type:'alarm',typeLabel:'吊车',x:55,y:57,statusLabel:'风险告警'},{id:'v1',name:'摄像头-12',short:'V',type:'camera',typeLabel:'摄像头',x:39,y:73},{id:'r1',name:'雷达-03',short:'R',type:'radar',typeLabel:'雷达',x:70,y:28},{id:'s1',name:'音柱-05',short:'S',type:'speaker',typeLabel:'音柱',x:80,y:66}]),polygons=ref([]),active=ref(null),state=ref({});const legend=[{label:'吊车 26',color:'#22d3ee'},{label:'摄像头 18',color:'#2f7dff'},{label:'雷达 8',color:'#8be9fd'},{label:'音柱 9',color:'#24c88b'},{label:'围栏 12',color:'#e9b949'}];const styleOf=m=>({left:`${m.x??50}%`,top:`${m.y??50}%`});function initMap(options={}){state.value={...options};return state.value}function addMarker(marker){markers.value.push({...marker,x:marker.x??50,y:marker.y??50});return marker}function addPolygon(polygon){polygons.value.push(polygon);return polygon}function clear(){markers.value=[];polygons.value=[];active.value=null}defineExpose({initMap,addMarker,addPolygon,clear})</script>
<style scoped>.map{position:relative;min-height:430px;height:100%;overflow:hidden;background:#071727;border:1px solid #1e4565}.grid{position:absolute;inset:0;background-image:linear-gradient(rgba(56,119,157,.13) 1px,transparent 1px),linear-gradient(90deg,rgba(56,119,157,.13) 1px,transparent 1px);background-size:48px 48px}.map::after{content:'';position:absolute;inset:0;background:radial-gradient(circle at 55% 50%,rgba(34,211,238,.08),transparent 34%);pointer-events:none}.line{position:absolute;height:7px;background:#173958;box-shadow:0 0 0 1px #204a6e;transform-origin:left}.a{width:82%;left:9%;top:43%;transform:rotate(-15deg)}.b{width:76%;left:16%;top:72%;transform:rotate(6deg)}.fence{position:absolute;padding:8px;color:#6da3c3;font-size:11px;border:1px solid rgba(34,211,238,.12);background:rgba(34,211,238,.06);clip-path:polygon(8% 0,92% 4%,100% 82%,54% 100%,0 77%)}.fa{left:24%;top:27%;width:36%;height:35%}.fb{left:68%;top:52%;width:24%;height:28%;color:var(--hg-gold);border-color:rgba(233,185,73,.18);background:rgba(233,185,73,.06)}.marker{position:absolute;z-index:3;display:flex;align-items:center;gap:7px;border:0;background:transparent;color:#dff8ff;cursor:pointer;transform:translate(-50%,-50%)}.marker span{display:grid;place-items:center;width:24px;height:24px;border:1px solid var(--hg-cyan);background:#07324a;box-shadow:0 0 12px rgba(34,211,238,.38);font:700 11px var(--hg-mono)}.marker b{padding:4px 7px;background:#06111f;border:1px solid #244967;font:500 10px var(--hg-mono)}.marker.alarm span{border-color:var(--hg-danger);background:#6a1725;box-shadow:0 0 16px rgba(255,77,94,.55)}.marker.camera span{border-color:var(--hg-blue)}.marker.speaker span{border-color:var(--hg-success)}.badge{position:absolute;right:12px;top:12px;z-index:4;padding:5px 8px;color:#78ddf4;background:#08233a;border:1px solid #1e5b79;font-size:11px}.pop{position:absolute;z-index:5;left:18px;bottom:52px;display:grid;gap:5px;min-width:210px;padding:12px;background:#0b1d31;border:1px solid var(--hg-cyan)}.pop span{font-size:12px;color:var(--hg-text2)}.pop button{justify-self:start;border:0;background:transparent;color:#71ddff;cursor:pointer}.legend{position:absolute;z-index:4;left:14px;bottom:13px;display:flex;gap:8px}.legend span{padding:5px 7px;background:#06111f;border:1px solid #24435f;color:#96afca;font-size:10px}.legend i{display:inline-block;width:6px;height:6px;margin-right:5px}@media(max-width:800px){.map{min-height:360px}.legend{right:10px;flex-wrap:wrap}}</style>
